"""Chapter 2: Distributed State & Actors - Solution 1: Stateful Actor Lifecycle.

Reference Solution for actors01.
"""

import os

os.environ["RAY_ENABLE_UV_RUN_RUNTIME_ENV"] = "0"
import ray


@ray.remote
class Counter:
    def __init__(self, initial_value: int = 0) -> None:
        self.count = initial_value

    def increment(self, step: int = 1) -> int:
        self.count += step
        return self.count

    def decrement(self, step: int = 1) -> int:
        self.count -= step
        return self.count

    def get_count(self) -> int:
        return self.count


def verify() -> None:
    ray.init(ignore_reinit_error=True)

    counter = Counter.remote(initial_value=10)
    counter.increment.remote(5)
    counter.decrement.remote(3)
    final_count = ray.get(counter.get_count.remote())

    assert final_count == 12, f"Expected final count 12, got {final_count}"
    print(
        f"✓ actors01 verified: Stateful Actor lifecycle and operations confirmed (count={final_count})!"
    )


if __name__ == "__main__":
    verify()

"""Chapter 2: Distributed State & Actors - Solution 3: Passing Actor Handles.

Reference Solution for actors03.
"""

import os

os.environ["RAY_ENABLE_UV_RUN_RUNTIME_ENV"] = "0"
import ray
from ray.actor import ActorHandle


@ray.remote
class MetricsLogger:
    def __init__(self) -> None:
        self.records: dict[str, int] = {}

    def log(self, worker_id: str, count: int) -> None:
        self.records[worker_id] = self.records.get(worker_id, 0) + count

    def get_total(self) -> int:
        return sum(self.records.values())


@ray.remote
class BatchWorker:
    def __init__(self, worker_id: str, logger: ActorHandle) -> None:
        self.worker_id = worker_id
        self.logger = logger

    def process(self, items: list[int]) -> int:
        total = sum(items)
        ray.get(self.logger.log.remote(self.worker_id, len(items)))
        return total


def verify() -> None:
    ray.init(ignore_reinit_error=True)

    logger = MetricsLogger.remote()

    batches = [
        ("worker_1", [1, 2, 3]),
        ("worker_2", [4, 5]),
        ("worker_3", [6, 7, 8, 9]),
    ]
    workers = [BatchWorker.remote(wid, logger) for wid, _ in batches]
    task_refs = [w.process.remote(items) for w, (_, items) in zip(workers, batches, strict=False)]
    batch_sums = ray.get(task_refs)
    total_items_logged = ray.get(logger.get_total.remote())

    assert batch_sums == [6, 9, 30], f"Expected batch sums [6, 9, 30], got {batch_sums}"
    assert total_items_logged == 9, f"Expected 9 total items logged, got {total_items_logged}"
    print(
        f"✓ actors03 verified: Actor handle passed across distributed worker actors (total={total_items_logged})!"
    )


if __name__ == "__main__":
    verify()

"""Chapter 2: Distributed State & Actors - Solution 6: Detached Named Actors.

Reference Solution for actors06.
"""

import os

os.environ["RAY_ENABLE_UV_RUN_RUNTIME_ENV"] = "0"
import ray


@ray.remote
class GlobalConfigRegistry:
    def __init__(self) -> None:
        self.config: dict[str, str] = {}

    def set(self, key: str, value: str) -> None:
        self.config[key] = value

    def get(self, key: str) -> str | None:
        return self.config.get(key)


def verify() -> None:
    ray.init(ignore_reinit_error=True)

    try:
        old_actor = ray.get_actor("app_config_registry")
        ray.kill(old_actor)
    except ValueError:
        pass

    registry = GlobalConfigRegistry.options(name="app_config_registry").remote()
    registry.set.remote("cluster_env", "production")

    discovered_handle = ray.get_actor("app_config_registry")
    retrieved_val = ray.get(discovered_handle.get.remote("cluster_env"))

    assert retrieved_val == "production", f"Expected 'production', but got '{retrieved_val}'"
    print(
        f"✓ actors06 verified: Named actor registered and retrieved by name successfully ('{retrieved_val}')!"
    )


if __name__ == "__main__":
    verify()

"""Chapter 3: Plasma Object Store & Zero-Copy - Solution 6: Custom Serializers with ray.util.

Reference Solution for object_store06.
"""

import os

os.environ["RAY_ENABLE_UV_RUN_RUNTIME_ENV"] = "0"
import math

import ray


class Vector3D:
    def __init__(self, x: float, y: float, z: float) -> None:
        self.x = x
        self.y = y
        self.z = z

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Vector3D):
            return False
        return (self.x, self.y, self.z) == (other.x, other.y, other.z)


def serialize_vector(vec: Vector3D) -> tuple[float, float, float]:
    return (vec.x, vec.y, vec.z)


def deserialize_vector(data: tuple[float, float, float]) -> Vector3D:
    return Vector3D(*data)


@ray.remote
def compute_magnitude(v: Vector3D) -> float:
    return math.sqrt(v.x**2 + v.y**2 + v.z**2)


def verify() -> None:
    ray.init(ignore_reinit_error=True)

    ray.util.register_serializer(
        Vector3D,
        serializer=serialize_vector,
        deserializer=deserialize_vector,
    )

    vec = Vector3D(3.0, 4.0, 12.0)

    mag_ref = compute_magnitude.remote(vec)
    mag = ray.get(mag_ref)

    assert math.isclose(mag, 13.0), f"Expected magnitude 13.0, got {mag}"
    print(f"✓ object_store06 verified: Custom serializer registered and executed magnitude={mag}!")


if __name__ == "__main__":
    verify()

