"""Chapter 5: Fault Tolerance & Recovery - Solution 2: Actor Failure & Automatic Restarts.

Reference Solution for fault02.
"""

import os

os.environ["RAY_ENABLE_UV_RUN_RUNTIME_ENV"] = "0"
import os
import time

import ray


@ray.remote(max_restarts=2, max_task_retries=0)
class SelfHealingActor:
    def __init__(self) -> None:
        self.created_at = time.time()

    def ping(self) -> str:
        return "pong"

    def crash(self) -> None:
        os._exit(1)


def verify() -> None:
    ray.init(ignore_reinit_error=True)

    actor = SelfHealingActor.remote()
    first_ping = ray.get(actor.ping.remote())

    try:
        ray.get(actor.crash.remote())
    except Exception:
        pass

    recovered_ping = None
    for _ in range(10):
        try:
            recovered_ping = ray.get(actor.ping.remote())
            break
        except Exception:
            time.sleep(0.5)

    assert first_ping == "pong", f"Expected first ping 'pong', got {first_ping}"
    assert recovered_ping == "pong", f"Expected recovered ping 'pong', got {recovered_ping}"
    print(
        f"✓ fault02 verified: SelfHealingActor crashed and recovered automatically (first={first_ping}, recovered={recovered_ping})!"
    )


if __name__ == "__main__":
    verify()

"""Chapter 5: Fault Tolerance & Recovery - Solution 4: Actor State Checkpointing.

Reference Solution for fault04.
"""

import os

os.environ["RAY_ENABLE_UV_RUN_RUNTIME_ENV"] = "0"
import os
import tempfile
import time
from pathlib import Path

import ray


@ray.remote(max_restarts=2, max_task_retries=0)
class CheckpointCounter:
    def __init__(self, checkpoint_file: str) -> None:
        self.checkpoint_file = Path(checkpoint_file)
        self.count = self._load_state()

    def _load_state(self) -> int:
        if self.checkpoint_file.exists():
            content = self.checkpoint_file.read_text(encoding="utf-8").strip()
            if content:
                return int(content)
        return 0

    def increment(self) -> int:
        self.count += 1
        self.checkpoint_file.write_text(str(self.count), encoding="utf-8")
        return self.count

    def get_count(self) -> int:
        return self.count

    def crash(self) -> None:
        os._exit(1)


def verify() -> None:
    ray.init(ignore_reinit_error=True)

    with tempfile.NamedTemporaryFile(delete=False) as tmp:
        ckpt_path = tmp.name

    try:
        actor = CheckpointCounter.remote(ckpt_path)

        for _ in range(5):
            ray.get(actor.increment.remote())

        try:
            ray.get(actor.crash.remote())
        except Exception:
            pass

        restored_count = None
        for _ in range(10):
            try:
                restored_count = ray.get(actor.get_count.remote())
                break
            except Exception:
                time.sleep(0.5)

        assert restored_count == 5, f"Expected restored count 5, got {restored_count}"
        print(
            f"✓ fault04 verified: Checkpoint state successfully recovered after actor crash (count={restored_count})!"
        )
    finally:
        if Path(ckpt_path).exists():
            Path(ckpt_path).unlink()


if __name__ == "__main__":
    verify()

"""Chapter 6: Cluster Topology & Multi-Node Architecture - Solution 1: Head Node, Workers & GCS.

Reference Solution for cluster01.
"""

import os

os.environ["RAY_ENABLE_UV_RUN_RUNTIME_ENV"] = "0"
import ray


def get_alive_node_count() -> int:
    nodes = ray.nodes()
    return sum(1 for n in nodes if n.get("Alive", False))


def get_total_cluster_cpus() -> float:
    nodes = ray.nodes()
    return sum(n.get("Resources", {}).get("CPU", 0.0) for n in nodes if n.get("Alive", False))


def verify() -> None:
    ray.init(ignore_reinit_error=True)

    alive_count = get_alive_node_count()
    total_cpus = get_total_cluster_cpus()

    assert alive_count is not None and alive_count >= 1, (
        f"Expected >=1 alive nodes, got {alive_count}"
    )
    assert total_cpus is not None and total_cpus >= 1.0, (
        f"Expected >=1.0 cluster CPUs, got {total_cpus}"
    )
    print(
        f"✓ cluster01 verified: Cluster topology inspected via GCS (nodes={alive_count}, total_cpus={total_cpus})!"
    )


if __name__ == "__main__":
    verify()

"""Chapter 7: Production Patterns & Anti-Patterns - Solution 1: Fixing ray.get() Inside Tasks.

Reference Solution for antipattern01.
"""

import os

os.environ["RAY_ENABLE_UV_RUN_RUNTIME_ENV"] = "0"
import ray


@ray.remote
def stage1() -> int:
    return 42


@ray.remote
def stage2(val: int) -> int:
    return val + 100


def verify() -> None:
    ray.init(ignore_reinit_error=True)

    ref1 = stage1.remote()
    ref2 = stage2.remote(ref1)
    result = ray.get(ref2)

    assert result == 142, f"Expected 142, got {result}"
    print(
        f"✓ antipattern01 verified: ObjectRef pipelined cleanly without blocking ray.get() inside tasks ({result})!"
    )


if __name__ == "__main__":
    verify()

"""Chapter 7: Production Patterns & Anti-Patterns - Solution 4: Tree-Structured Reduction (Tree-Reduce).

Reference Solution for antipattern04.
"""

import os

os.environ["RAY_ENABLE_UV_RUN_RUNTIME_ENV"] = "0"
import ray


@ray.remote
def add_pair(a: int, b: int) -> int:
    return a + b


@ray.remote
def produce_leaf(val: int) -> int:
    return val


def tree_reduce(refs: list[ray.ObjectRef]) -> ray.ObjectRef:
    current = list(refs)
    while len(current) > 1:
        next_level = []
        for i in range(0, len(current), 2):
            if i + 1 < len(current):
                next_level.append(add_pair.remote(current[i], current[i + 1]))
            else:
                next_level.append(current[i])
        current = next_level
    return current[0]


def verify() -> None:
    ray.init(ignore_reinit_error=True)

    values = [1, 2, 3, 4, 5, 6, 7, 8]
    leaf_refs = [produce_leaf.remote(v) for v in values]
    root_ref = tree_reduce(leaf_refs)
    total = ray.get(root_ref)

    assert total == 36, f"Expected total 36 (sum of 1..8), got {total}"
    print(
        f"✓ antipattern04 verified: Tree-reduction computed 8 leaf nodes in O(log2 N) depth (total={total})!"
    )


if __name__ == "__main__":
    verify()

"""Chapter 9: Distributed ML Primitives from Scratch - Solution 1: Distributed Parameter Server.

Reference Solution for ml_scratch01.
"""

import os

os.environ["RAY_ENABLE_UV_RUN_RUNTIME_ENV"] = "0"
import numpy as np
import ray


@ray.remote
class ParameterServer:
    def __init__(self, dim: int, lr: float = 0.1) -> None:
        self.weights = np.zeros(dim, dtype=np.float32)
        self.lr = lr

    def get_weights(self) -> list[float]:
        return self.weights.tolist()

    def apply_gradient(self, grad: list[float]) -> list[float]:
        self.weights -= self.lr * np.array(grad, dtype=np.float32)
        return self.weights.tolist()


@ray.remote
def compute_gradient(weights: list[float], x: float, y: float) -> list[float]:
    w = weights[0]
    pred = w * x
    grad = 2.0 * (pred - y) * x
    return [grad]


def verify() -> None:
    ray.init(ignore_reinit_error=True)

    ps = ParameterServer.remote(dim=1, lr=0.05)
    for _ in range(10):
        w = ray.get(ps.get_weights.remote())
        g = ray.get(compute_gradient.remote(w, 2.0, 4.0))
        ray.get(ps.apply_gradient.remote(g))

    final_weight = ray.get(ps.get_weights.remote())

    assert abs(final_weight[0] - 2.0) < 0.1, f"Expected weight ~2.0, got {final_weight[0]}"
    print(f"✓ ml_scratch01 verified: ParameterServer converged to {final_weight[0]:.4f}!")
    ray.shutdown()


if __name__ == "__main__":
    verify()

"""Chapter 12: Ray Serve - Solution 3: Composable Multi-Model Pipelines (DAGs).

Reference Solution for serve03.
"""

import os

os.environ["RAY_ENABLE_UV_RUN_RUNTIME_ENV"] = "0"
import ray
from ray import serve
from ray.serve.handle import DeploymentHandle


@serve.deployment
class Tokenizer:
    def __call__(self, text: str) -> str:
        return text.strip().lower()


@serve.deployment
class Classifier:
    def __call__(self, clean_text: str) -> dict:
        return {"label": "positive" if "good" in clean_text else "neutral"}


@serve.deployment
class Pipeline:
    def __init__(self, tokenizer: DeploymentHandle, classifier: DeploymentHandle) -> None:
        self.tokenizer = tokenizer
        self.classifier = classifier

    async def __call__(self, raw_text: str) -> dict:
        clean = await self.tokenizer.remote(raw_text)
        return await self.classifier.remote(clean)


def verify() -> None:
    ray.init(ignore_reinit_error=True)

    app = Pipeline.bind(Tokenizer.bind(), Classifier.bind())
    handle = serve.run(app)
    assert handle is not None, "Handle must not be None"

    ref = handle.remote("  VERY GOOD PRODUCT  ")
    result = ref.result()
    assert result == {"label": "positive"}, f"Expected positive label, got {result}"
    print(f"✓ serve03 verified: Composable DAG pipeline returned: {result}!")
    serve.shutdown()
    ray.shutdown()


if __name__ == "__main__":
    verify()

"""Chapter 12: Ray Serve - Solution 5: Serve Autoscaling Policies.

Reference Solution for serve05.
"""

import os

os.environ["RAY_ENABLE_UV_RUN_RUNTIME_ENV"] = "0"
import ray
from ray import serve


@serve.deployment(
    autoscaling_config={
        "min_replicas": 1,
        "max_replicas": 3,
        "target_ongoing_requests": 1,
    }
)
class AutoscaledWorker:
    def __call__(self, request_id: int) -> dict:
        return {"status": "ok", "id": request_id}


def verify() -> None:
    ray.init(ignore_reinit_error=True)

    handle = serve.run(AutoscaledWorker.bind())
    assert handle is not None, "Handle must not be None"

    refs = [handle.remote(i) for i in range(3)]
    results = [r.result() for r in refs]
    assert len(results) == 3, f"Expected 3 results, got {len(results)}"
    assert all(r["status"] == "ok" for r in results)
    print(
        f"✓ serve05 verified: Autoscaled Serve deployment handled {len(results)} concurrent requests cleanly!"
    )
    serve.shutdown()
    ray.shutdown()


if __name__ == "__main__":
    verify()

"""Chapter 14: KubeRay - Solution 1: RayCluster Custom Resource (CRD).

Reference Solution for kuberay01.
"""

import os

os.environ["RAY_ENABLE_UV_RUN_RUNTIME_ENV"] = "0"
from typing import Any


def build_ray_cluster_crd(
    name: str, ray_version: str, min_workers: int, max_workers: int
) -> dict[str, Any]:
    return {
        "apiVersion": "ray.io/v1",
        "kind": "RayCluster",
        "metadata": {"name": name},
        "spec": {
            "rayVersion": ray_version,
            "headGroupSpec": {
                "rayStartParams": {"dashboard-host": "0.0.0.0"},
                "template": {
                    "spec": {
                        "containers": [
                            {
                                "name": "ray-head",
                                "image": f"rayproject/ray:{ray_version}",
                                "resources": {
                                    "limits": {"cpu": "2", "memory": "4Gi"},
                                    "requests": {"cpu": "2", "memory": "4Gi"},
                                },
                            }
                        ]
                    }
                },
            },
            "workerGroupSpecs": [
                {
                    "groupName": "default-worker",
                    "minReplicas": min_workers,
                    "maxReplicas": max_workers,
                    "template": {
                        "spec": {
                            "containers": [
                                {
                                    "name": "ray-worker",
                                    "image": f"rayproject/ray:{ray_version}",
                                    "resources": {
                                        "limits": {"cpu": "2", "memory": "4Gi"},
                                        "requests": {"cpu": "2", "memory": "4Gi"},
                                    },
                                }
                            ]
                        }
                    },
                }
            ],
        },
    }


def verify() -> None:
    crd = build_ray_cluster_crd(
        name="ray-ml-cluster",
        ray_version="2.40.0",
        min_workers=2,
        max_workers=8,
    )

    assert crd is not None, "CRD must not be None"
    assert crd.get("apiVersion") == "ray.io/v1", f"Invalid apiVersion: {crd.get('apiVersion')}"
    assert crd.get("kind") == "RayCluster", f"Invalid kind: {crd.get('kind')}"
    assert crd["metadata"]["name"] == "ray-ml-cluster"

    spec = crd["spec"]
    assert spec["rayVersion"] == "2.40.0"
    assert "headGroupSpec" in spec
    assert spec["headGroupSpec"]["rayStartParams"]["dashboard-host"] == "0.0.0.0"

    workers = spec["workerGroupSpecs"][0]
    assert workers["groupName"] == "default-worker"
    assert workers["minReplicas"] == 2
    assert workers["maxReplicas"] == 8

    print(
        f"✓ kuberay01 verified: RayCluster CRD for '{crd['metadata']['name']}' built and validated!"
    )


if __name__ == "__main__":
    verify()

