                    "rayStartParams": {"dashboard-host": "0.0.0.0"},
                    "template": {
                        "spec": {
                            "containers": [{"name": "ray-head", "image": "rayproject/ray:2.40.0"}]
                        }
                    },
                },
                "workerGroupSpecs": [
                    {
                        "groupName": "serve-worker",
                        "minReplicas": 1,
                        "maxReplicas": 5,
                        "template": {
                            "spec": {
                                "containers": [
                                    {"name": "ray-worker", "image": "rayproject/ray:2.40.0"}
                                ]
                            }
                        },
                    }
                ],
            },
        },
